import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {openPreviewStore} from './sqlite-preview-store.mjs';
import {createModerationRoute} from './moderation-route.mjs';
const path='/articles/ratchet-wrench.html',origin='https://preview.invalid';
const adapter=(t)=>{
 const dir=mkdtempSync(join(tmpdir(),'comments-synthetic-'));
 const options={file:join(dir,'trial.sqlite'),eligible:[path],operatorIds:['admin']};
 const handles=[];
 t.after(()=>{for(const db of handles)db.close();rmSync(dir,{recursive:true,force:true});});
 return ()=>{const db=openPreviewStore(options);handles.push(db);return db;};
};
const post=(db,options={})=>db.post(path,'author',{nickname:'テスト投稿者',body:'架空の本文',requestId:'request-a',...options});
const routeFor=db=>createModerationRoute({origin,identity:{authenticate:async token=>token==='admin'?{id:'admin',anonymous:false}:null},moderators:{has:id=>id==='admin'},store:db});
const call=(route,token,body)=>route(new Request(origin+'/api/article-comments/moderation',{method:body?'POST':'GET',headers:{authorization:'Bearer '+token,...(body?{origin,'content-type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})}));
test('store persists across connections, keeps pending out of public data, and rejects stale approval',async t=>{
 const open=adapter(t),first=open(),second=open();
 const id=post(first);
 assert.equal(post(second),id);
 assert.throws(()=>post(second,{body:'変更して同じキー'}),{status:409});
 assert.deepEqual(second.publicFor(path),[]);assert.deepEqual(second.ownFor(path,'other'),[]);
 assert.equal(second.ownFor(path,'author')[0].body,'架空の本文');
 const a=routeFor(first),b=routeFor(second);
 assert.equal((await call(a,'another-reader')).status,403);
 const rr=await call(a,'admin');const [r]=(await rr.json()).rows;
 assert.equal(rr.headers.get('cache-control'),'private, no-store');
 second.editOwn(path,id,'author',{nickname:'テスト投稿者',body:'確認する新しい版',consent:true});
 const approval={id,path,action:'approve',rev:r.rev};
 assert.equal((await call(a,'admin',approval)).status,409);
 assert.deepEqual(second.publicFor(path),[]);
 const [current]=(await (await call(b,'admin')).json()).rows;
 assert.equal((await call(a,'admin',{...approval,rev:current.rev})).status,200);
 assert.deepEqual(open().publicFor(path).map(r=>r.body),['確認する新しい版']);
 assert.equal((await call(b,'admin',{id,path,action:'hide',rev:current.rev+1})).status,200);
 assert.deepEqual(first.publicFor(path),[]);
});
test('parent approval and hide also control reply visibility and remove article consent on moderator edit',t=>{
 const db=adapter(t)(),id=post(db,{consent:true});
 const mod=(object)=>db.apply({path,adminId:'admin',...object});
 const approve=id=>{
  const pending=db.list({adminId:'admin',state:'pending',limit:50}).find(r=>r.id===id);
  mod({id,action:'approve',rev:pending.rev});
 };
 assert.throws(()=>post(db,{parent:id,requestId:'reply'}),{status:409});
 approve(id);
 const reply=post(db,{parent:id,requestId:'reply'});
 approve(reply);assert.equal(db.publicFor(path).length,2);
 assert.throws(()=>post(db,{parent:reply,requestId:'nested'}),{status:409});
 assert.throws(()=>db.post('/en/articles/ratchet-wrench.html','author',{body:'test'}),{status:404});
 assert.throws(()=>db.editOwn(path,id,'other',{nickname:'',body:'no'}),{status:403});
 assert.equal(db.list({adminId:'admin',state:'published',limit:50}).find(r=>r.id===id).mayFeature,true);
 mod({id,action:'edit',rev:db.list({adminId:'admin',state:'published',limit:50}).find(r=>r.id===id).rev,nickname:'運営編集',body:'修正案',consent:true});
 assert.equal(db.publicFor(path)[0].body,'架空の本文');
 assert.equal(db.list({adminId:'admin',state:'published',limit:50}).find(r=>r.id===id).mayFeature,false);
 approve(id);assert.equal(db.list({adminId:'admin',state:'published',limit:50}).find(r=>r.id===id).mayFeature,false);
 mod({id,action:'hide',rev:db.list({adminId:'admin',state:'published',limit:50}).find(r=>r.id===id).rev});assert.deepEqual(db.publicFor(path),[]);
});
test('article route and dashboard use the same SQL rows with identity-independent public responses',async t=>{
 const {createArticleRoute}=await import('./article-route.mjs');
 const db=adapter(t)();
 const who=req=>new Map([['author-cookie','author'],['reader-cookie','reader']]).get(req.headers.get('cookie'));
 const a=createArticleRoute({origin,sessions:{read:who,ensure:async req=>({actor:who(req)??'author',cookie:'trial=local; HttpOnly; Secure; SameSite=Strict; Path=/'})},store:db});
 const m=routeFor(db);
 const get=(view,cookie)=>a(new Request(origin+'/api/article-comments/'+view+'?article='+encodeURIComponent(path),{headers:{cookie}}));
 const name='承認待ちの合成名',body='識別できる合成本⽂';
 const submit=(cookie,op)=>a(new Request(origin+'/api/article-comments/'+op+'?article='+encodeURIComponent(path),{method:'POST',headers:{origin,'content-type':'application/json',cookie},body:JSON.stringify(op==='post'?{action:'post',body,nickname:name,requestId:'round-trip'}:{})}));
 assert.equal((await submit('','post')).status,401);
 assert.deepEqual(db.list({adminId:'admin',state:'pending',limit:50}),[]);
 const bootstrap=await submit('','session');assert.equal(bootstrap.status,200);assert.match(bootstrap.headers.get('set-cookie'),/HttpOnly; Secure; SameSite=Strict/);
 const send=await submit('author-cookie','post');
 assert.equal((await submit('author-cookie','post')).status,200);
 assert.equal(db.list({adminId:'admin',state:'pending',limit:50}).length,1);
 assert.equal(send.status,200);assert.equal((await send.json()).rows[0].body,body);
 const own=await get('own','author-cookie'),other=await get('own','reader-cookie');
 assert.equal(own.headers.get('cache-control'),'private, no-store');
 assert.equal((await own.json()).rows[0].nickname,name);
 const raw=await other.text();assert(!raw.includes(name)&&!raw.includes(body));
 const published=async()=>{const a=await get('public','author-cookie'),b=await get('public','reader-cookie');assert.equal(b.headers.get('cache-control'),'no-store');assert.equal(b.headers.get('set-cookie'),null);assert.equal(await a.text(),await b.clone().text());return (await b.json()).rows;};
 assert.deepEqual(await published(),[]);
 const [todo]=(await (await call(m,'admin')).json()).rows;
 assert.equal(todo.nickname,name);
 assert.equal((await call(m,'admin',{id:todo.id,path,action:'approve',rev:todo.rev})).status,200);
 assert.equal((await published())[0].body,body);
 assert.equal((await call(m,'admin',{id:todo.id,path,action:'hide',rev:todo.rev+1})).status,200);
 assert.deepEqual(await published(),[]);
});
